reference_solution:
def can_split_consecutive(nums):
    available = Counter(nums)
    endings = Counter()
    for value in nums:
        if available[value] == 0: continue
        available[value] -= 1
        if endings[value - 1]:
            endings[value - 1] -= 1
            endings[value] += 1
        elif available[value + 1] and available[value + 2]:
            available[value + 1] -= 1
            available[value + 2] -= 1
            endings[value + 2] += 1
        else:
            return False
    return True

